import React, { useState } from "react";
import "./style.css";
import { Helmet, HelmetProvider } from "react-helmet-async";
import { Container, Row, Col } from "react-bootstrap";
import { Link, useParams, Navigate } from "react-router-dom";
import { meta } from "../../content_option";
import { useLanguage } from "../../i18n/LanguageContext";
import { blogPosts } from "../../data/blogData";

// Lightweight markdown renderer — handles ## h2, ### h3, - list, paragraphs
const renderContent = (text) => {
  const lines = text.split("\n");
  const elements = [];
  let buffer = [];

  const flushBuffer = () => {
    if (buffer.length > 0) {
      const joined = buffer.join(" ").trim();
      if (joined) {
        elements.push(
          <p key={`p-${elements.length}`} className="post-content__paragraph">
            {joined}
          </p>
        );
      }
      buffer = [];
    }
  };

  lines.forEach((line, idx) => {
    if (line.startsWith("## ")) {
      flushBuffer();
      elements.push(
        <h2 key={idx} className="post-content__h2">
          {line.slice(3)}
        </h2>
      );
    } else if (line.startsWith("### ")) {
      flushBuffer();
      elements.push(
        <h3 key={idx} className="post-content__h3">
          {line.slice(4)}
        </h3>
      );
    } else if (line.startsWith("- ")) {
      flushBuffer();
      elements.push(
        <p key={idx} className="post-content__li">
          {line.slice(2)}
        </p>
      );
    } else if (line.trim() === "") {
      flushBuffer();
    } else {
      buffer.push(line);
    }
  });
  flushBuffer();
  return elements;
};

export const BlogPost = () => {
  const { slug } = useParams();
  const { t, language } = useLanguage();
  const [copySuccess, setCopySuccess] = useState(false);

  // Bilingual slug lookup: slugs differ per language
  const currentPosts = blogPosts[language] || blogPosts.en;
  const otherLang = language === "en" ? "pt" : "en";
  let post = currentPosts.find((p) => p.slug === slug);

  if (!post) {
    const crossPost = (blogPosts[otherLang] || []).find((p) => p.slug === slug);
    if (crossPost) post = currentPosts.find((p) => p.id === crossPost.id);
  }

  if (!post) return <Navigate to="/blog" replace />;

  // Related posts (same category, exclude current)
  const relatedPosts = currentPosts
    .filter((p) => p.category === post.category && p.id !== post.id)
    .slice(0, 3);

  // Formatted date
  const formattedDate = new Date(post.date).toLocaleDateString(
    language === "pt" ? "pt-BR" : "en-US",
    { year: "numeric", month: "long", day: "numeric" }
  );

  // Author initials for avatar
  const initials = post.author
    .replace(/^Dr\.?\s*/i, "")
    .split(" ")
    .map((n) => n[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();

  // Category label from translations (fallback to raw value)
  const categoryKey = `blogPost.categories.${post.category}`;
  const categoryLabel = t(categoryKey) !== categoryKey
    ? t(categoryKey)
    : post.category.toUpperCase();

  // Social sharing
  const pageUrl = encodeURIComponent(window.location.href);
  const postTitle = encodeURIComponent(post.title);
  const shareUrls = {
    twitter: `https://twitter.com/intent/tweet?url=${pageUrl}&text=${postTitle}`,
    linkedin: `https://www.linkedin.com/sharing/share-offsite/?url=${pageUrl}`,
    whatsapp: `https://api.whatsapp.com/send?text=${postTitle}%20${pageUrl}`,
    facebook: `https://www.facebook.com/sharer/sharer.php?u=${pageUrl}`,
  };
  const handleShare = (platform) => {
    window.open(shareUrls[platform], "_blank", "noopener,noreferrer,width=600,height=500");
  };
  const handleCopyLink = async () => {
    try {
      await navigator.clipboard.writeText(window.location.href);
    } catch {
      const el = document.createElement("input");
      el.value = window.location.href;
      el.style.position = "fixed";
      el.style.left = "-9999px";
      document.body.appendChild(el);
      el.select();
      document.execCommand("copy");
      document.body.removeChild(el);
    }
    setCopySuccess(true);
    setTimeout(() => setCopySuccess(false), 2500);
  };

  // JSON-LD schema
  const schema = {
    "@context": "https://schema.org",
    "@type": "BlogPosting",
    headline: post.title,
    description: post.excerpt,
    image: post.image,
    author: { "@type": "Person", name: post.author, jobTitle: post.authorRole },
    publisher: { "@type": "Organization", name: "Tyber.io", url: "https://tyber.io" },
    datePublished: post.date,
    dateModified: post.date,
    url: window.location.href,
    keywords: post.tags.join(", "),
    articleSection: categoryLabel,
    inLanguage: language === "pt" ? "pt-BR" : "en",
  };

  return (
    <HelmetProvider>
      <article className="blogpost-page">
        <Helmet>
          <html lang={language === 'pt' ? 'pt-BR' : 'en'} />
          <title>{post.title} | {meta.title}</title>
          <meta name="description" content={post.excerpt} />
          <meta name="keywords" content={post.tags.join(", ")} />
          <link rel="canonical" href={window.location.href} />

          {/* Open Graph */}
          <meta property="og:type" content="article" />
          <meta property="og:title" content={post.title} />
          <meta property="og:description" content={post.excerpt} />
          <meta property="og:image" content={post.image} />
          <meta property="og:url" content={window.location.href} />
          <meta property="og:site_name" content="Tyber.io" />
          <meta property="article:published_time" content={post.date} />
          <meta property="article:author" content={post.author} />
          <meta property="article:section" content={categoryLabel} />
          {post.tags.map((tag, i) => (
            <meta key={i} property="article:tag" content={tag} />
          ))}

          {/* Twitter Card */}
          <meta name="twitter:card" content="summary_large_image" />
          <meta name="twitter:title" content={post.title} />
          <meta name="twitter:description" content={post.excerpt} />
          <meta name="twitter:image" content={post.image} />
          <meta name="twitter:site" content="@tyber_io" />

          {/* JSON-LD */}
          <script type="application/ld+json">{JSON.stringify(schema)}</script>
        </Helmet>

        {/* Back link */}
        <Container className="blogpost-back">
          <Link to="/blog" className="back-link">
            <span className="back-link__arrow">←</span>
            {t("blogPost.backTo")}
          </Link>
        </Container>

        {/* Hero */}
        <div className="blogpost-hero">
          <Container>
            <div className="blogpost-hero__meta">
              <span className="blogpost-hero__category">{categoryLabel}</span>
              <span className="meta-dot">·</span>
              <span>{t("blogPost.publishedOn")} {formattedDate}</span>
              <span className="meta-dot">·</span>
              <span>{post.readTime} {t("blogPost.readTime")}</span>
            </div>
            <h1 className="blogpost-hero__title">{post.title}</h1>
            <p className="blogpost-hero__excerpt">{post.excerpt}</p>
            <div className="blogpost-hero__author">
              <div className="author-avatar">
                <span className="author-avatar__initials">{initials}</span>
              </div>
              <div>
                <div className="author-info__name">{post.author}</div>
                <div className="author-info__role">{post.authorRole}</div>
              </div>
            </div>
          </Container>
        </div>

        {/* Featured image */}
        <Container className="blogpost-image-wrap">
          <div className="blogpost-featured-image">
            <img src={post.image} alt={post.title} loading="eager" />
          </div>
        </Container>

        {/* Body */}
        <Container className="blogpost-body">
          <Row>
            <Col lg={8}>
              {/* Article content */}
              <div className="post-content">
                {renderContent(post.content)}
              </div>

              {/* Tags */}
              <div className="post-tags">
                <span className="post-tags__label">{t("blogPost.tagsLabel")}:</span>
                <div className="post-tags__list">
                  {post.tags.map((tag, i) => (
                    <span key={i} className="post-tag">{tag}</span>
                  ))}
                </div>
              </div>

              {/* Social sharing */}
              <div className="post-share">
                <h4 className="post-share__title">{t("blogPost.shareTitle")}</h4>
                <div className="post-share__buttons">
                  <button className="share-btn share-btn--twitter" onClick={() => handleShare("twitter")} aria-label={t("blogPost.shareTwitter")}>
                    <span className="share-btn__icon">𝕏</span>
                    <span className="share-btn__label">{t("blogPost.shareTwitter")}</span>
                  </button>
                  <button className="share-btn share-btn--linkedin" onClick={() => handleShare("linkedin")} aria-label={t("blogPost.shareLinkedin")}>
                    <span className="share-btn__icon">in</span>
                    <span className="share-btn__label">{t("blogPost.shareLinkedin")}</span>
                  </button>
                  <button className="share-btn share-btn--whatsapp" onClick={() => handleShare("whatsapp")} aria-label={t("blogPost.shareWhatsapp")}>
                    <span className="share-btn__icon">W</span>
                    <span className="share-btn__label">{t("blogPost.shareWhatsapp")}</span>
                  </button>
                  <button className="share-btn share-btn--facebook" onClick={() => handleShare("facebook")} aria-label={t("blogPost.shareFacebook")}>
                    <span className="share-btn__icon">f</span>
                    <span className="share-btn__label">{t("blogPost.shareFacebook")}</span>
                  </button>
                  <button
                    className={`share-btn share-btn--copy${copySuccess ? " copied" : ""}`}
                    onClick={handleCopyLink}
                    aria-label={t("blogPost.copyLink")}
                  >
                    <span className="share-btn__icon">⎘</span>
                    <span className="share-btn__label">
                      {copySuccess ? t("blogPost.linkCopied") : t("blogPost.copyLink")}
                    </span>
                  </button>
                </div>
              </div>
            </Col>

            {/* Sidebar */}
            <Col lg={4}>
              <aside className="blogpost-sidebar">
                <div className="author-card">
                  <p className="author-card__label">{t("blogPost.authorTitle")}</p>
                  <div className="author-card__avatar">
                    <span className="author-card__initials">{initials}</span>
                  </div>
                  <div className="author-card__name">{post.author}</div>
                  <div className="author-card__role">{post.authorRole}</div>
                </div>
              </aside>
            </Col>
          </Row>
        </Container>

        {/* Related posts */}
        {relatedPosts.length > 0 && (
          <Container className="blogpost-related">
            <h2 className="related-title">{t("blogPost.relatedTitle")}</h2>
            <Row>
              {relatedPosts.map((relPost) => (
                <Col lg={4} md={6} key={relPost.id} className="mb-4">
                  <article className="blog-card">
                    <div className="blog-card__image">
                      <img src={relPost.image} alt={relPost.title} loading="lazy" />
                      <div className="blog-card__category">{relPost.category.toUpperCase()}</div>
                    </div>
                    <div className="blog-card__content">
                      <div className="blog-card__meta">
                        <span className="date">{relPost.date}</span>
                        <span className="separator">·</span>
                        <span className="read-time">{relPost.readTime} {t("blogPost.readTime")}</span>
                      </div>
                      <h3 className="blog-card__title">{relPost.title}</h3>
                      <p className="blog-card__excerpt">{relPost.excerpt}</p>
                      <Link to={`/blog/${relPost.slug}`} className="blog-card__link">
                        {t("blog.readMore")} →
                      </Link>
                    </div>
                  </article>
                </Col>
              ))}
            </Row>
          </Container>
        )}
      </article>
    </HelmetProvider>
  );
};
